import {type LoaderFunctionArgs} from '@shopify/remix-oxygen';
import {useLoaderData, type MetaFunction, Await} from 'react-router';
import {Suspense} from 'react';
import {
  getSelectedProductOptions,
  Analytics,
  useOptimisticVariant,
  getProductOptions,
  getAdjacentAndFirstAvailableVariants,
  useSelectedOptionInUrlParam,
} from '@shopify/hydrogen';
import {motion} from 'framer-motion';
import {AdvancedProductGallery} from '~/components/AdvancedProductGallery';
import {ProductGallery} from '~/components/ProductGallery';
import {ProductInfo} from '~/components/ProductInfo';
import {ProductReviews} from '~/components/ProductReviews';
import {ProductRecommendations} from '~/components/ProductRecommendations';
import {TrustSignals} from '~/components/TrustSignals';
import {SizeGuide} from '~/components/SizeGuide';
import {ProductQandA} from '~/components/ProductQandA';
import {ProductComparison} from '~/components/ProductComparison';
import {InstagramFeed} from '~/components/InstagramFeed';
import {redirectIfHandleIsLocalized} from '~/lib/redirect';
import {staggerContainer, staggerItem} from '~/lib/design-system';

export const meta: MetaFunction<typeof loader> = ({data}) => {
  const title = data?.product?.seo?.title || data?.product?.title || 'Product';
  const description = data?.product?.seo?.description || data?.product?.description || '';
  const url = `/products/${data?.product?.handle ?? ''}`;
  return [
    {title: `Hydrogen | ${title}`},
    {name: 'description', content: description},
    {rel: 'canonical', href: url},
    {property: 'og:title', content: title},
    {property: 'og:description', content: description},
    {property: 'og:url', content: url},
    {name: 'twitter:card', content: 'summary_large_image'},
  ];
};

export async function loader(args: LoaderFunctionArgs) {
  // Start fetching non-critical data without blocking time to first byte
  const deferredData = loadDeferredData(args);

  // Await the critical data required to render initial state of the page
  const criticalData = await loadCriticalData(args);

  const {storefront} = args.context;
  const {country, language} = storefront.i18n;

  return {
    ...deferredData,
    ...criticalData,
    i18n: {country, language},
  };
}

/**
 * Load data necessary for rendering content above the fold. This is the critical data
 * needed to render the page. If it's unavailable, the whole page should 400 or 500 error.
 */
async function loadCriticalData({
  context,
  params,
  request,
}: LoaderFunctionArgs) {
  const {handle} = params;
  const {storefront} = context;

  if (!handle) {
    throw new Error('Expected product handle to be defined');
  }

  const [{product}] = await Promise.all([
    storefront.query(PRODUCT_QUERY, {
      variables: {handle, selectedOptions: getSelectedProductOptions(request)},
    }),
    // Add other queries here, so that they are loaded in parallel
  ]);

  if (!product?.id) {
    throw new Response(null, {status: 404});
  }

  // The API handle might be localized, so redirect to the localized handle
  redirectIfHandleIsLocalized(request, {handle, data: product});

  return {
    product,
  };
}

/**
 * Load data for rendering content below the fold. This data is deferred and will be
 * fetched after the initial page load. If it's unavailable, the page should still 200.
 * Make sure to not throw any errors here, as it will cause the page to 500.
 */
function loadDeferredData({context}: LoaderFunctionArgs) {
  // Load recommended products
  const recommendedProducts = context.storefront
    .query(PRODUCT_RECOMMENDATIONS_QUERY)
    .catch((error) => {
      console.error(error);
      return null;
    });

  return {
    recommendedProducts,
  };
}

export default function Product() {
  const {product, recommendedProducts, i18n} = useLoaderData<typeof loader>();
  
  // Optimistically selects a variant with given available variant information
  const selectedVariant = useOptimisticVariant(
    product.selectedOrFirstAvailableVariant,
    getAdjacentAndFirstAvailableVariants(product),
  );

  // Sets the search param to the selected variant without navigation
  // only when no search params are set in the url
  useSelectedOptionInUrlParam(selectedVariant.selectedOptions);

  // Get the product options array
  const productOptions = getProductOptions({
    ...product,
    selectedOrFirstAvailableVariant: selectedVariant,
  });
  const track = (eventName: string, payload: Record<string, unknown> = {}) => {
    try {
      // eslint-disable-next-line no-console
      console.debug('[track]', eventName, payload);
    } catch {
      // Silent catch for analytics tracking
    }
  };

  const FREE_SHIPPING_THRESHOLD = 50;
  const estimateEtaDays = (countryCode?: string) => {
    if (!countryCode) return 7;
    switch (countryCode) {
      case 'US':
      case 'CA':
        return 5;
      case 'GB':
      case 'EU':
        return 6;
      default:
        return 8;
    }
  };

  const etaDays = estimateEtaDays(i18n?.country);
  
  const {title} = product;

  return (
    <motion.div 
      className="min-h-screen bg-secondary-25"
      variants={staggerContainer}
      initial="initial"
      animate="animate"
    >
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Breadcrumb */}
        <motion.nav 
          className="flex mb-8" 
          aria-label="Breadcrumb"
          variants={staggerItem}
        >
          <ol className="flex items-center space-x-2 text-sm text-secondary-600">
            <li>
              <a href="/" className="hover:text-secondary-900 transition-colors">
                Home
              </a>
            </li>
            <li className="flex items-center">
              <svg className="w-4 h-4 mx-2" fill="currentColor" viewBox="0 0 20 20">
                <path fillRule="evenodd" d="M7.293 14.707a1 1 0 010-1.414L10.586 10 7.293 6.707a1 1 0 011.414-1.414l4 4a1 1 0 010 1.414l-4 4a1 1 0 01-1.414 0z" clipRule="evenodd" />
              </svg>
              <a href="/collections" className="hover:text-secondary-900 transition-colors">
                Collections
              </a>
            </li>
            <li className="flex items-center">
              <svg className="w-4 h-4 mx-2" fill="currentColor" viewBox="0 0 20 20">
                <path fillRule="evenodd" d="M7.293 14.707a1 1 0 010-1.414L10.586 10 7.293 6.707a1 1 0 011.414-1.414l4 4a1 1 0 010 1.414l-4 4a1 1 0 01-1.414 0z" clipRule="evenodd" />
              </svg>
              <span className="text-secondary-900 font-medium">{title}</span>
            </li>
          </ol>
        </motion.nav>

        {/* Product Main Content */}
        <motion.div 
          className="bg-white rounded-2xl shadow-sm overflow-hidden mb-12"
          variants={staggerItem}
        >
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-0">
            {/* Product Gallery */}
            <div className="p-8 bg-secondary-25">
              {AdvancedProductGallery ? (
                <AdvancedProductGallery
                  product={product}
                />
              ) : (
                <ProductGallery 
                  product={product} 
                  selectedVariant={selectedVariant} 
                />
              )}
            </div>

            {/* Product Info */}
            <div className="p-8 lg:p-12 lg:sticky lg:top-24 self-start">
              <ProductInfo
                product={product}
                selectedVariant={selectedVariant}
                productOptions={productOptions}
              />
              <div className="mt-6 space-y-4">
                <div className="flex items-center justify-between gap-4">
                  <div className="text-sm text-secondary-700">
                    <button
                      type="button"
                      className="underline underline-offset-2"
                      aria-label="Open size guide"
                      onClick={() => track('ClickSizeGuide', {productId: product.id})}
                    >
                      Size Guide
                    </button>
                    <span className="mx-2 text-secondary-300">|</span>
                    <button
                      type="button"
                      className="underline underline-offset-2"
                      aria-label="View shipping info"
                      onClick={() => track('ViewShippingInfo', {country: i18n?.country})}
                    >
                      {`ETA ${etaDays}-${etaDays + 2} ngày`}
                    </button>
                  </div>
                  <div className="text-sm font-medium text-primary-700">
                    {selectedVariant?.price?.amount ? (
                      Number(selectedVariant.price.amount) >= FREE_SHIPPING_THRESHOLD ? (
                        <span>Miễn phí vận chuyển</span>
                      ) : (
                        <span>
                          Còn {Math.max(0, FREE_SHIPPING_THRESHOLD - Number(selectedVariant.price.amount)).toFixed(0)} để freeship
                        </span>
                      )
                    ) : null}
                  </div>
                </div>

                <TrustSignals variant="product" showStats={false} />

                <div className="sr-only" aria-hidden>
                  <SizeGuide />
                </div>
              </div>
            </div>
          </div>
        </motion.div>

        {/* Product Reviews */}
        <motion.div 
          className="mb-12"
          variants={staggerItem}
        >
          <ProductReviews productId={product.id} />
        </motion.div>

        {/* Product Recommendations */}
        <motion.div variants={staggerItem}>
          <Suspense fallback={null}>
            <Await resolve={recommendedProducts}>
              {(data: any) => (
                <ProductRecommendations
                  currentProductId={product.id}
                  products={data?.products?.nodes || []}
                />
              )}
            </Await>
          </Suspense>
        </motion.div>

        {/* Q&A and Comparison */}
        <motion.div className="mb-12" variants={staggerItem}>
          <ProductQandA productId={product.id} productName={product.title} />
        </motion.div>
        <motion.div className="mb-12" variants={staggerItem}>
          <ProductComparison
            currentProduct={{
              id: product.id,
              title: product.title,
              price: `${selectedVariant?.price?.amount ?? '0'} ${selectedVariant?.price?.currencyCode ?? ''}`.trim(),
              rating: 4.6,
              image: product?.selectedOrFirstAvailableVariant?.image?.url,
            }}
          />
        </motion.div>

        {/* Instagram Social Proof */}
        <motion.div variants={staggerItem}>
          <InstagramFeed title="Customers Love It" />
        </motion.div>

        {/* Analytics */}
        <Analytics.ProductView
          data={{
            products: [
              {
                id: product.id,
                title: product.title,
                price: selectedVariant?.price.amount || '0',
                vendor: product.vendor,
                variantId: selectedVariant?.id || '',
                variantTitle: selectedVariant?.title || '',
                quantity: 1,
              },
            ],
          }}
        />
        {/* Mobile Sticky CTA Bar */}
        <div className="lg:hidden fixed inset-x-0 bottom-0 z-40 bg-white/95 backdrop-blur border-t border-secondary-200">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-3">
            <div className="flex items-center justify-between gap-4">
              <div className="flex flex-col">
                <span className="text-xs text-secondary-600">Total</span>
                <span className="text-lg font-semibold text-secondary-900">
                  {selectedVariant?.price ? (
                    <>
                      {selectedVariant.price.amount} {selectedVariant.price.currencyCode}
                    </>
                  ) : (
                    '—'
                  )}
                </span>
                <span className="text-[11px] text-secondary-600">
                  {`ETA ${etaDays}-${etaDays + 2} ngày`}
                </span>
                {selectedVariant?.price?.amount ? (
                  <span className="text-[11px] text-primary-700">
                    {Number(selectedVariant.price.amount) >= FREE_SHIPPING_THRESHOLD
                      ? 'Miễn phí vận chuyển'
                      : `Còn ${Math.max(0, FREE_SHIPPING_THRESHOLD - Number(selectedVariant.price.amount)).toFixed(0)} để freeship`}
                  </span>
                ) : null}
              </div>
              {selectedVariant?.id ? (
                <div className="flex-1">
                  {/* Lightweight inline AddToCart for mobile */}
                  <form action="/cart" method="post">
                    <input type="hidden" name="cartAction" value="ADD_TO_CART" />
                    <input type="hidden" name="lines" value={JSON.stringify([{merchandiseId: selectedVariant.id, quantity: 1}])} />
                    <button
                      type="submit"
                      className="w-full inline-flex items-center justify-center rounded-lg bg-primary-600 text-white font-semibold py-3 shadow-md active:scale-[0.99]"
                      disabled={!selectedVariant?.availableForSale}
                      aria-disabled={!selectedVariant?.availableForSale}
                      aria-label="Add to cart"
                      onClick={() => track('AddToCart', {productId: product.id, variantId: selectedVariant.id})}
                    >
                      {selectedVariant?.availableForSale ? 'Add to Cart' : 'Out of Stock'}
                    </button>
                  </form>
                  {selectedVariant?.availableForSale ? (
                    <button
                      type="button"
                      className="mt-2 w-full inline-flex items-center justify-center rounded-lg bg-secondary-900 text-white font-semibold py-3 shadow-md active:scale-[0.99]"
                      onClick={() => track('BuyNowClick', {productId: product.id, variantId: selectedVariant.id})}
                      aria-label="Buy now"
                    >
                      Buy Now
                    </button>
                  ) : null}
                </div>
              ) : (
                <button
                  className="flex-1 inline-flex items-center justify-center rounded-lg bg-secondary-300 text-secondary-700 font-semibold py-3 shadow-md"
                  disabled
                  aria-disabled
                >
                  Select options
                </button>
              )}
            </div>
          </div>
        </div>

        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{
            __html: JSON.stringify(buildProductJsonLd(product, selectedVariant)),
          }}
        />
      </div>
    </motion.div>
  );
}

function buildProductJsonLd(product: any, selectedVariant: any) {
  const price = selectedVariant?.price?.amount || (product as any)?.priceRange?.minVariantPrice?.amount || '0';
  const currency = selectedVariant?.price?.currencyCode || (product as any)?.priceRange?.minVariantPrice?.currencyCode || 'USD';
  const availability = selectedVariant?.availableForSale ? 'http://schema.org/InStock' : 'http://schema.org/OutOfStock';
  return {
    '@context': 'https://schema.org/',
    '@type': 'Product',
    name: product?.title,
    description: product?.seo?.description || product?.description,
    sku: selectedVariant?.sku,
    brand: {
      '@type': 'Brand',
      name: product?.vendor,
    },
    offers: {
      '@type': 'Offer',
      priceCurrency: currency,
      price,
      availability,
      url: `/products/${product?.handle}`,
    },
  } as const;
}

const PRODUCT_VARIANT_FRAGMENT = `#graphql
  fragment ProductVariant on ProductVariant {
    availableForSale
    compareAtPrice {
      amount
      currencyCode
    }
    id
    image {
      __typename
      id
      url
      altText
      width
      height
    }
    price {
      amount
      currencyCode
    }
    product {
      title
      handle
    }
    selectedOptions {
      name
      value
    }
    sku
    title
    unitPrice {
      amount
      currencyCode
    }
  }
` as const;

const PRODUCT_FRAGMENT = `#graphql
  fragment Product on Product {
    id
    title
    vendor
    handle
    descriptionHtml
    description
    encodedVariantExistence
    encodedVariantAvailability
    featuredImage {
      id
      url
      altText
      width
      height
    }
    images(first: 12) {
      nodes {
        id
        url
        altText
        width
        height
      }
    }
    media(first: 12) {
      nodes {
        mediaContentType
        previewImage {
          url
        }
        ... on MediaImage {
          image {
            id
            url
            altText
            width
            height
          }
        }
        ... on Video {
          id
          sources {
            url
            mimeType
          }
          previewImage {
            url
          }
        }
        ... on ExternalVideo {
          id
          embeddedUrl
        }
        ... on Model3d {
          id
          sources {
            url
          }
        }
      }
    }
    options {
      name
      optionValues {
        name
        firstSelectableVariant {
          ...ProductVariant
        }
        swatch {
          color
          image {
            previewImage {
              url
            }
          }
        }
      }
    }
    selectedOrFirstAvailableVariant(selectedOptions: $selectedOptions, ignoreUnknownOptions: true, caseInsensitiveMatch: true) {
      ...ProductVariant
    }
    adjacentVariants (selectedOptions: $selectedOptions) {
      ...ProductVariant
    }
    seo {
      description
      title
    }
  }
  ${PRODUCT_VARIANT_FRAGMENT}
` as const;

const PRODUCT_QUERY = `#graphql
  query Product(
    $country: CountryCode
    $handle: String!
    $language: LanguageCode
    $selectedOptions: [SelectedOptionInput!]!
  ) @inContext(country: $country, language: $language) {
    product(handle: $handle) {
      ...Product
    }
  }
  ${PRODUCT_FRAGMENT}
` as const;

const PRODUCT_RECOMMENDATIONS_QUERY = `#graphql
  fragment ProductRecommendation on Product {
    id
    title
    handle
    vendor
    priceRange {
      minVariantPrice {
        amount
        currencyCode
      }
      maxVariantPrice {
        amount
        currencyCode
      }
    }
    featuredImage {
      id
      url
      altText
      width
      height
    }
  }
  query ProductRecommendations($country: CountryCode, $language: LanguageCode)
    @inContext(country: $country, language: $language) {
    products(first: 8, sortKey: UPDATED_AT, reverse: true) {
      nodes {
        ...ProductRecommendation
      }
    }
  }
` as const;
